import { writeFileSync } from 'node:fs';
const cases = [];
// --- underscore emphasis with word-char boundaries (Python \w is Unicode-aware)
const WORDISH = ['a', '1', '_', '中', 'あ', '한', 'Ω', 'é', 'А', 'ا', 'ñ', 'ᚠ', 'ⅷ', '𝐀', '½', '①', '一'];
const NONWORD = [' ', '.', ',', '、', '。', '（', '）', '「', '」', '－', '·', '！', '？', '：', '；', '"', '—', '‘'];
