  cases.push(c + '_em_' + c);
  cases.push(c + '_em_');
  cases.push('_em_' + c);
  cases.push(c + '__st__' + c);
}
for (const c of NONWORD) {
  cases.push(c + '_em_' + c);
  cases.push(c + '__st__' + c);
}
// --- asterisk emphasis adjacent to CJK / punctuation
